const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const source = JSON.parse(fs.readFileSync('/var/folders/j2/k150yy6d74ld6gm3rk77rjkr0000gn/T/php-ai-toolkit-ci-vlg9e84m/issue-script.json', 'utf8'));
const AsyncFunction = Object.getPrototypeOf(async function () {}).constructor;
const run = new AsyncFunction('require', 'process', 'context', 'core', 'github', source);
async function check(name, stats, issues = [], missing = false) {
  const calls = [];
  const file = path.join('packages', name, 'build/infection/infection.json');
  const mockFs = {
    existsSync: value => { assert.equal(value, file); return !missing; },
    readFileSync: value => { assert.equal(value, file); return JSON.stringify({ stats }); },
  };
  const summary = { addHeading() { return this; }, addRaw() { return this; }, async write() { calls.push(['summary']); } };
  await run(
    id => id === 'node:fs' ? mockFs : require(id),
    { env: { PACKAGE: name, MIN_MSI: '80', MIN_COVERED_MSI: '80', GITHUB_RUN_ATTEMPT: '1' } },
    { workflow: 'Mutation', serverUrl: 'https://github.com', repo: { owner: 'test', repo: 'test' }, runId: 1, sha: 'test' },
    { summary },
    {
      paginate: async () => issues,
      rest: { issues: {
        listForRepo() {},
        create: async args => calls.push(['create', args]),
        update: async args => calls.push(['update', args]),
      } },
    },
  );
  return calls;
}
