  assert.match(first.title, /docgen-php/);
  assert.match(first.body, /<!-- Mutation:docgen-php:msi -->/);
  assert.match(first.body, /mutation-reports-docgen-php/);
  const otherIssue = { number: 1, ...first };
  const second = (await check('guard-php', low, [otherIssue])).find(([type]) => type === 'create')[1];
  assert.match(second.body, /<!-- Mutation:guard-php:msi -->/);
  const update = (await check('guard-php', { msi: 90, coveredCodeMsi: 79 }, [otherIssue, { number: 2, ...second }])).find(([type]) => type === 'update')[1];
  assert.equal(update.issue_number, 2);
  await assert.rejects(check('docgen-php', { msi: 101, coveredCodeMsi: 80 }), /valid MSI/);
  await assert.rejects(check('docgen-php', low, [], true), /did not write the report for docgen-php/);
  console.log('PASS: mutation issue creation, package isolation, updates, thresholds and invalid/missing reports');
})().catch(error => { console.error(error); process.exit(1); });
